SELECT

FROM
iot_device_property
WHERE
del_flag = '0'

    AND device_id = #{property.deviceId}


    AND device_code = #{property.deviceCode}


    AND product_id = #{property.productId}


    AND identifier = #{property.identifier}


    AND name LIKE CONCAT('%', #{property.name}, '%')


    AND factory_code = #{property.factoryCode}

ORDER BY collect_time DESC

SELECT p.*, d.device_code, d.device_name
FROM iot_device_property p
LEFT JOIN iot_device d ON p.device_id = d.id
WHERE 1=1

    AND p.device_id IN

        #{deviceId}



    AND p.identifier = #{identifier}


    AND p.create_time >= #{startTime}


    AND p.create_time <= #{endTime}

ORDER BY p.create_time DESC

SELECT p.*, d.device_code, d.device_name
FROM iot_device_property p
LEFT JOIN iot_device d ON p.device_id = d.id
WHERE d.product_id = #{productId}

    AND p.identifier = #{identifier}


    AND p.create_time >= #{startTime}


    AND p.create_time <= #{endTime}

ORDER BY p.create_time DESC
